"""Byte-exact remote arguments across POSIX and fish login-shell parsing."""
from __future__ import annotations

import contextlib
import io
import os
import shlex
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

from district import host


def fish_model(command: str, **kwargs) -> subprocess.CompletedProcess:
    # Translate fish's single-quoted backslash escapes to their POSIX equivalents.
    # Everything else generated by shlex.join uses the same syntax in these shells.
    script = []
    quote = None
    index = 0
    while index < len(command):
        char = command[index]
        if (quote == "'" and char == "\\" and index + 1 < len(command)
                and command[index + 1] in "\\'"):
            index += 1
            char = command[index]
            script.append("'\"'\"'" if char == "'" else char)
        else:
            script.append(char)
            if char == quote:
                quote = None
            elif quote is None and char in "'\"":
                quote = char
            elif char == "\\" and quote != "'" and index + 1 < len(command):
                index += 1
                script.append(command[index])
        index += 1
    return subprocess.run(["sh", "-c", "".join(script)], capture_output=True, **kwargs)


class RemoteShellTest(unittest.TestCase):
    def test_remote_argv_is_byte_exact_across_login_shells(self) -> None:
        values = [r"a\\b", "x\\", "\\", "'", '"', "$HOME", ";", "&&", " ", "\n", "", "café"]
        argv = ["printf", "%s\\0", *values]
        expected = b"".join(value.encode() + b"\0" for value in values)
        shells = ["sh", "bash", "fish-model"]
        shells.extend(shell for shell in ("zsh", "fish") if shutil.which(shell))
        with tempfile.TemporaryDirectory() as directory:
            cwd = Path(directory) / "cwd ' \\ $HOME"
            cwd.mkdir()
            for shell in shells:
                for layers in (False, True):
                    with self.subTest(shell=shell, layers=layers):
                        def transport(ssh, *, timeout=None, input=None):
                            kwargs = {"timeout": timeout, "input": input.encode() if input is not None else None}
                            if shell == "fish-model":
                                proc = fish_model(ssh[-1], **kwargs)
                            else:
                                proc = subprocess.run([shell, "-c", ssh[-1]], capture_output=True, **kwargs)
                            return subprocess.CompletedProcess(ssh, proc.returncode,
                                                               proc.stdout.decode(), proc.stderr.decode())

                        runner = host.RemoteRunner("remote", "unused", transport=transport)
                        options = {"cwd": cwd, "env": {"DISTRICT_SHELL_VALUE": "'\\$HOME\n"}, "timeout": 10} if layers else {}
                        output = io.StringIO()
                        with contextlib.redirect_stdout(output):
                            proc = runner(argv, **options)
                        self.assertEqual(proc.returncode, 0, proc.stderr)
                        self.assertEqual(proc.stdout.encode(), expected)
                        self.assertEqual(output.getvalue(), f"remote: $ {shlex.join(argv)}\n")
                        if layers:
                            script = 'printf "%s\\0" "$PWD" "$DISTRICT_SHELL_VALUE"; cat'
                            proc = runner(["sh", "-c", script], input="stdin ' \\\n", quiet=True, **options)
                            self.assertEqual(proc.returncode, 0, proc.stderr)
                            self.assertEqual(proc.stdout.encode(),
                                             os.fsencode(cwd) + b"\0'\\$HOME\n\0stdin ' \\\n")


if __name__ == "__main__":
    unittest.main()
